const int N = 100100;

int n, p;
int l[N], r[N];

int main(){
	sd2(n,p);

	for(int i = 0; i < n; i++){
		sd2(l[i], r[i]);
	}

	l[n] = l[0];
	r[n] = r[0];

	long double res = 0;

	for(int i = 1; i <= n; i++){
		long long v1 = (r[i]/p) - ((l[i]-1)/p);
		long long v2 = (r[i-1]/p) - ((l[i-1]-1)/p);

		long long l1 = r[i]-l[i]+1;
		long long l2 = r[i-1]-l[i-1]+1;

		long long t = (l1-v1)*(l2-v2);

		long double p = (long double) t / (long double) (l1*l2);

		p = 1.0f-p;
		res += p*2000;
	}

	printf("%.9lf\n", (double)res);

	return 0;
}

